import{_ as t,a as n,b as i,c as r}from"./chunks/presets-04.Dx-DqE4-.js";import{_ as s,o as a,c as l,a3 as o}from"./chunks/framework.D1iekJsc.js";const f=JSON.parse('{"title":"Presets","description":"MiniTavern Prompt-Presets — Basis-Prompts und eine sortierbare Prompt-Liste. Sampling bleibt in den Modelleinstellungen.","frontmatter":{"title":"Presets","description":"MiniTavern Prompt-Presets — Basis-Prompts und eine sortierbare Prompt-Liste. Sampling bleibt in den Modelleinstellungen.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"Presets · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Prompt-Presets — Basis-Prompts und eine sortierbare Prompt-Liste. Sampling bleibt in den Modelleinstellungen."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/manual/presets"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/manual/presets"}]]},"headers":[],"relativePath":"de/manual/presets.md","filePath":"de/manual/presets.md","lastUpdated":1791862671000}'),d={name:"de/manual/presets.md"};function u(h,e,p,g,c,m){return a(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="presets" tabindex="-1">Presets <a class="header-anchor" href="#presets" aria-label="Permalink to &quot;Presets&quot;">​</a></h1><p>Pfad: unten <strong>Einstellungen</strong> → <strong>Presets</strong>.</p><p>Ein Preset ist eine komplette Prompt-Struktur und ändert Schreibweise und Vorgaben im Roleplay. Temperatur und anderes Sampling bleiben unter <strong>Modelleinstellungen</strong>.</p><h2 id="schritte" tabindex="-1">Schritte <a class="header-anchor" href="#schritte" aria-label="Permalink to &quot;Schritte&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+t+'" alt="Presets in den Einstellungen"><figcaption>1 · Einstellungen → Presets</figcaption></figure><figure class="shot-step"><img src="'+n+'" alt="Preset-Liste"><figcaption>2 · Liste und New</figcaption></figure><figure class="shot-step"><img src="'+i+'" alt="Preset bearbeiten"><figcaption>3 · Name, Basic prompts, Prompts</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="Neuen Prompt anlegen"><figcaption>4 · Neuer Prompt</figcaption></figure></div><p>Die Schaltflächen auf dieser Seite heißen in der App englisch.</p><h2 id="liste" tabindex="-1">Liste <a class="header-anchor" href="#liste" aria-label="Permalink to &quot;Liste&quot;">​</a></h2><ol><li><strong>New</strong> legt ein Preset an oder importiert ein SillyTavern-Chat-Completion-Preset. Sampling-Schlüssel werden ignoriert, mit Hinweis auf die Modelleinstellungen.</li><li>Nach der Installation gibt es nur die Zeile mit dem Tag <strong>Standard</strong>. Sie lässt sich nicht bearbeiten und nicht löschen.</li><li>Das Menü einer Zeile kann nach oben verschieben, als Standard setzen, bearbeiten, duplizieren, exportieren oder löschen.</li><li>Neu und Duplizieren öffnen zuerst den Editor. Die Zeile erscheint erst nach <strong>Save</strong>.</li></ol><h2 id="preset-bearbeiten" tabindex="-1">Preset bearbeiten <a class="header-anchor" href="#preset-bearbeiten" aria-label="Permalink to &quot;Preset bearbeiten&quot;">​</a></h2><ul><li><strong>Name</strong> ist Pflicht.</li><li><strong>Basic prompts</strong> umfasst Persona, Beschreibung, Persönlichkeit, Szenario, Beispielchat-Beginn, neuen Chat-Beginn und Lorebuch.</li><li>Die Liste <strong>Prompts</strong> ist durchsuchbar. Lang drücken sortiert. Ein eingeschalteter Eintrag gilt für normales Senden; ausgeschaltete bleiben inaktiv und werden nicht injiziert.</li><li><strong>Add</strong> öffnet einen neuen Prompt. Eigene Einträge lassen sich bearbeiten, duplizieren und löschen. Eingebaute Einträge erlauben nur Name und Inhalt.</li></ul><p>Hauptprompt und Post-History der Charakterkarte überschreiben die passenden Preset-Einträge. Szenariotext kommt zuerst aus den Chat-Einstellungen, dann von der Karte, zuletzt aus dem Klartext in den Basic prompts.</p><p>Fortsetzen, neu erzeugen und Smart Reply lesen dieses Preset nicht. Nur normales Senden baut die Prompts in Listenreihenfolge.</p><h2 id="neuer-prompt" tabindex="-1">Neuer Prompt <a class="header-anchor" href="#neuer-prompt" aria-label="Permalink to &quot;Neuer Prompt&quot;">​</a></h2><ol><li><strong>Name</strong> ist Pflicht.</li><li><strong>Role</strong> startet als SYSTEM und lässt sich ändern.</li><li><strong>Injection position</strong> <strong>Relative</strong> setzt den Prompt an seine Stelle in der Liste. <strong>In-chat</strong> zeigt <strong>Injection depth</strong> und fügt ihn in dieser Tiefe in die Historie ein.</li><li><strong>Content</strong> ist der Prompt-Text. Makros sind möglich.</li><li><strong>Save</strong> kehrt zum Preset-Editor zurück.</li></ol><h2 id="nur-dieser-chat" tabindex="-1">Nur dieser Chat <a class="header-anchor" href="#nur-dieser-chat" aria-label="Permalink to &quot;Nur dieser Chat&quot;">​</a></h2><p>Pfad: Dialog → <strong>Chat-Einstellungen</strong> → Modell → <strong>Presets</strong>.</p><p>Standard ist dem Standard-Preset folgen. Ausgeschaltet gilt die Wahl nur für diesen Chat.</p><h2 id="siehe-auch" tabindex="-1">Siehe auch <a class="header-anchor" href="#siehe-auch" aria-label="Permalink to &quot;Siehe auch&quot;">​</a></h2><ul><li><a href="./model-link">Modellverbindung</a>: Sampling bleibt in den Modelleinstellungen</li><li><a href="./persona">Persona</a> · <a href="./lorebook">Weltbuch</a>: Basic prompts können sie einbeziehen</li></ul>',19)])])}const S=s(d,[["render",u]]);export{f as __pageData,S as default};
